from copy import deepcopy
from typing import Any


def _response(status: int, content_type: str, body: Any) -> dict[str, Any]:
    return {"status": status, "content_type": content_type, "body": body}


def resolve_asset(catalog: dict[str, Any], path: str) -> dict[str, Any]:
    if not isinstance(catalog, dict):
        raise ValueError("catalog must be a dictionary")
    for bundle_id, bundle in catalog.items():
        if not isinstance(bundle_id, str) or not bundle_id or not isinstance(bundle, dict):
            raise ValueError("invalid bundle")
        if set(("manifest", "icons", "symbols")) - bundle.keys():
            raise ValueError("bundle is missing required data")
        if not isinstance(bundle["manifest"], dict) or not isinstance(bundle["icons"], dict) or not isinstance(bundle["symbols"], dict):
            raise ValueError("invalid bundle sections")
        for scale, variants in bundle["icons"].items():
            if scale not in {"1", "2"} or not isinstance(variants, dict):
                raise ValueError("invalid icon scale")
            if set(variants) != {"png", "json"}:
                raise ValueError("icon variants must contain png and json")
            if not isinstance(variants["png"], bytes) or not isinstance(variants["json"], dict):
                raise ValueError("invalid icon data")
        for key, data in bundle["symbols"].items():
            if not isinstance(key, tuple) or len(key) != 3 or not isinstance(data, bytes):
                raise ValueError("invalid symbol entry")
            family, start, end = key
            if not isinstance(family, str) or not family:
                raise ValueError("invalid symbol family")
            if any(not isinstance(value, int) or isinstance(value, bool) for value in (start, end)) or start < 0 or start > end:
                raise ValueError("invalid symbol range")
    if not isinstance(path, str):
        raise ValueError("path must be a string")

    parts = path.split("/")
    bad = lambda: _response(400, "application/json", {"error": "bad request"})
    missing = lambda: _response(404, "application/json", {"error": "not found"})
    if len(parts) < 5 or parts[:3] != ["", "v1", "bundles"] or not parts[3]:
        return bad()
    bundle_id = parts[3]
    bundle = catalog.get(bundle_id)

    if len(parts) == 5 and parts[4] == "manifest":
        if bundle is None:
            return missing()
        body = deepcopy(bundle["manifest"])
        body["icon_template"] = f"/v1/bundles/{bundle_id}/icons/{{scale}}/{{kind}}"
        body["symbol_template"] = f"/v1/bundles/{bundle_id}/symbols/{{family}}/{{start}}-{{end}}"
        return _response(200, "application/json", body)

    if len(parts) == 7 and parts[4] == "icons" and parts[5] in {"1", "2"} and parts[6] in {"png", "json"}:
        if bundle is None:
            return missing()
        scale = "1" if parts[5] == "2" else parts[5]
        variants = bundle["icons"].get(scale)
        if variants is None:
            return missing()
        kind = parts[6]
        media = "image/png" if kind == "png" else "application/json"
        return _response(200, media, deepcopy(variants[kind]))

    if len(parts) == 7 and parts[4] == "symbols" and parts[5]:
        bounds = parts[6].split("-")
        if len(bounds) != 2 or not all(value.isdigit() for value in bounds):
            return bad()
        start, end = map(int, bounds)
        if start > end:
            return bad()
        if bundle is None:
            return missing()
        data = bundle["symbols"].get((parts[5], start, end))
        if data is None:
            return missing()
        return _response(200, "application/octet-stream", deepcopy(data))

    return bad()

